INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(113897, 'ruRU', '', 'Ещё один безымянный громила Саргераса, притворяющийся помощником этих эльфов. Они и не подозревают о своей судьбе.', 24330),
(113898, 'ruRU', '', 'Предатель своего мира и своего народа. Его конец никогда не был под вопросом... лишь то, кто его принесёт.', 24330),
(113899, 'ruRU', '', 'Ох, куда же она могла уйти...', 24330),
(113901, 'ruRU', '', 'Как?', 24330),
(113905, 'ruRU', '', 'То, что этот идиотский нарыв Н''Зота прожил так долго... это мало что меняет в моём мнении о новых владельцах этого мира.', 24330),
(113907, 'ruRU', '', 'Как низко пали Манашторм! Опора на грубые машины и слабое тайное колдовство не принесла им добра. И всё же от них была своя польза.', 24330),
(113908, 'ruRU', '', 'Её мать была куда внушительнее. Голод этой неукротим, а тактика избита. Лёгкая цель.', 24330),
(113909, 'ruRU', '', 'Право же, эти прихвостни Саргераса ТАК взаимозаменяемы. Этот неплох с топором. Ох, как оригинально!', 24330),
(113911, 'ruRU', '', 'Ещё один глупец, поверивший лживым речам Иллидана о жертве и праведности. Измученный, он обращается против всех.', 24330),
(113925, 'ruRU', '', 'Это создание старое, но всё же не из первых. Эти существа были слишком жадны до магии, чтобы подчиняться нашим хозяевам, хотя время от времени от них всё же есть польза.', 24330),
(113926, 'ruRU', '', 'Земля, полная снов, и ни одного — обо мне? Этого достаточно, чтобы задеть девичью гордость.', 24330),
(113927, 'ruRU', '', 'Когда, по-твоему, она переметнулась? Века назад? Она прячет свою жажду власти за плащом страдания и праведности.', 24330),
(113929, 'ruRU', '', 'Эти трое достаточно долго пользовались тайной благосклонностью Н''Зота. К сожалению, их дни разбоя окончены.', 24330),
(113930, 'ruRU', '', 'Могучий дракон мог бы стать мощным орудием. Увы, дни Галакронда давно минули.', 24330),
(113935, 'ruRU', '', 'Нам нужны ответы!', 24330),
(113936, 'ruRU', '', 'Подкрепление из Стальгорна уже прибывает. Штормград не падёт на нашей страже!', 24330),
(113967, 'ruRU', '', 'Великие драконы, склонившиеся перед волей Ксавия, что служит Богу Глубин. Вместо того чтобы дарить жизнь, она поглощает всё вокруг себя.', 24330),
(113968, 'ruRU', '', 'Похоже, темница Н''Зота уже не так прочна, как прежде. То, что ты видишь — лишь крошечный отросток исполина, что однажды может поглотить твой мир.', 24330),
(113969, 'ruRU', '', 'Ещё одно семя порчи, посаженное смертью. Неупокоенный дух будет бродить в гневе и расти в боли. Лёгкая добыча для Бога Глубин.', 24330),
(113970, 'ruRU', '', 'Ещё один защитник титанов повержен. Каждая смерть облегчает дело. Возможно, теперь его страдания закончатся... хотя я в этом сомневаюсь.', 24330),
(113972, 'ruRU', '', 'Развращение стражей Сна — смелый шаг, но Ксавий, возможно, замахнулся слишком широко. Ему было бы лучше тихо распространять влияние Кошмара, а не поднимать такую тревогу.', 24330),
(113973, 'ruRU', '', 'Разрушение этой земли — незаконченная работа. Завершённая, она станет достойным даром великому Саргерасу.', 24330),
(113974, 'ruRU', '', 'Ксавий хорошо использует силу своего нового хозяина. Искажение разума полубога — не пустяковый подвиг.', 24330),
(113978, 'ruRU', '', 'Ксавий, перебегающий от одного хозяина к другому. Отчаянно рвущийся к власти, но раз за разом терпящий поражение. Бог Глубин выбрал неудачного защитника, или здесь есть что-то ещё?', 24330),
(113979, 'ruRU', '', 'Почти полностью исчезло, будто его и не существовало вовсе. Но Разлом глубок и обширен, и где-то там, внизу, оно шевелится. Что-то изменилось, последняя темница слабеет. Нам нужно готовиться.', 24330),
(113982, 'ruRU', '', 'Стены между мирами здесь тонки, их так легко разорвать. Знаешь ли ты, что случится, если здесь встретятся истинная тень и истинный свет?', 24330),
(113984, 'ruRU', '', 'Исследования Пустоты здесь достойны похвалы, но в конечном счёте бесполезны. Как ты можешь понять то, чего не поняли даже титаны?', 24330),
(113985, 'ruRU', '', 'Я знаю, что наару считают нас ужасами, которым нужно противостоять. Мы не разделяем этот взгляд. Они лишь возлюбленные братья, сбившиеся с истинного пути. Они вернутся к своим хозяевам... со временем.', 24330),
(113987, 'ruRU', '', 'Ты собрал немалую группу последователей. Хорошо, что они сосредоточены на этом вторжении, а не на истинной войне. Её масштаб мог бы разрушить ваши разумы.', 24330),
(113988, 'ruRU', '', 'Говорят ли наару о вечном конфликте? О том, что вся история твоего мира — лишь крошечная доля прошедшего времени? О тех, кто пришёл до дренеев? Нет? <короткий смешок>', 24330),
(113989, 'ruRU', '', 'Восхитительно.', 24330),
(113990, 'ruRU', '', 'Каждая маленькая смерть идёт на пользу.', 24330),
(113991, 'ruRU', '', 'Понравилось?', 24330),
(113992, 'ruRU', '', 'Скучно.', 24330),
(113993, 'ruRU', '', 'Только погляди на это, брат!', 24330),
(113994, 'ruRU', '', 'Ты почувствовал, как оно перестало существовать?', 24330),
(113995, 'ruRU', '', 'Помнишь, как королева Азшара сотрудничала с демонами? Ну, видимо, когда принц Фарондис узнал об этом, он такой...', 24330),
(113996, 'ruRU', '', '"НЕТ!"', 24330),
(113997, 'ruRU', '', '...а потом королева Азшара такая...', 24330),
(113998, 'ruRU', '', '"КАК ТЫ СМЕЕШЬ МНЕ ПРОТИВИТЬСЯ!?"', 24330);
